/// <summary>
/// This is a service class for account status update job.
/// </summary>
class METAccountStatusUpdateService extends METSysOperationService
{
    guid topPickingProcessId;

}

Method.Source:
/// <summary>
/// Returns name of the task service class.
/// </summary>
/// <returns>Task service class name</returns>
protected str getTaskServiceClass()
{
    return classStr(METAccountStatusUpdateTaskService);
}

/// <summary>
/// Returns name of the task service class method.
/// </summary>
/// <returns>Task service class method name</returns>
protected str getTaskServiceClassMethod()
{
    return methodStr(METAccountStatusUpdateTaskService, process);
}

/// <summary>
/// Returns caption of the task service class.
/// </summary>
/// <returns>Task service class caption</returns>
protected str getTaskServiceCaption()
{
    return "@MET:AccountStatusUpdate";
}

/// <summary>
/// Executes the main process.
/// </summary>
/// <param name = "_contract">
/// <c>METSysOperationTaskDataContract</c>
/// </param>
public void process(METAccountStatusUpdateContract _contract)
{
    this.processInternal(_contract);
}

/// <summary>
/// Initialise global variables.
/// </summary>
public void initialise()
{
    super();

    METAccountStatusUpdateContract contract = dataContract as METAccountStatusUpdateContract;

    this.stageDataIntoQueue(contract);
}

/// <summary>
/// Stages data int table <c>METABNValidationJobQueue</c>.
/// </summary>
/// <param name = "_contract">
/// <c>METAccountStatusUpdateContract</c>.
/// </param>
void stageDataIntoQueue(METAccountStatusUpdateContract _contract)
{
    RecordInsertList accountStatusUpdateRecordList;
    METAccountStatusUpdateQueue queue;
    QueryRun queryRun;

    accountStatusUpdateRecordList = new RecordInsertList(tableNum(METAccountStatusUpdateQueue));
    topPickingProcessId = newGuid();
    queryRun = new QueryRun(_contract.getQuery());

    METAccountStatusUpdateQueue::cleanUpQueue();

    while (queryRun.next())
    {
        CustTable custTable = queryRun.get(tableNum(CustTable));

        queue.clear();
        queue.ProcessId = topPickingProcessId;
        queue.CustAccount = custTable.AccountNum;

        accountStatusUpdateRecordList.add(queue);
    }

    ttsbegin;
    accountStatusUpdateRecordList.insertDatabase();
    ttscommit;

}

/// <summary>
/// Initializes the task data contract.
/// </summary>
/// <param name = "_taskDataContract">task data contract</param>
protected void initTaskDataContract(METSysOperationTaskDataContract _taskDataContract)
{
    super(_taskDataContract);
    METAccountStatusUpdateContract contract = _taskDataContract as METAccountStatusUpdateContract;
    contract.parmTopPickingProcessId(topPickingProcessId);
}

/// <summary>
/// Provides task data contract.
/// </summary>
/// <returns>task data contract</returns>
protected METSysOperationTaskDataContract taskDataContractObject()
{
    return new METAccountStatusUpdateContract();
}
